package com.isp.customers.dto;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Past;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;

/**
 * Payload used to create a customer. The creation date is generated by the
 * server, therefore it is not part of this request.
 */
public record CreateCustomerRequest(
        @NotBlank(message = "nombre is required")
        @Size(max = 100, message = "nombre must have at most 100 characters")
        String nombre,

        @NotBlank(message = "apellido is required")
        @Size(max = 100, message = "apellido must have at most 100 characters")
        String apellido,

        @NotBlank(message = "email is required")
        @Email(message = "email must be a valid address")
        @Size(max = 150, message = "email must have at most 150 characters")
        String email,

        @NotBlank(message = "dni is required")
        @Pattern(regexp = "\\d{8}", message = "dni must contain exactly 8 digits")
        String dni,

        @NotNull(message = "fechaNacimiento is required")
        @Past(message = "fechaNacimiento must be a past date")
        LocalDate fechaNacimiento) {}
